<script setup>
import { session, logout, errorText } from '../../services/api'
import { useRouter } from 'vue-router'
import { ref } from 'vue'
const router=useRouter(), error=ref(''), busy=ref(false)
async function signOut(){busy.value=true;try{await logout();await router.push('/login')}catch(e){error.value=errorText(e)}finally{busy.value=false}}
</script>
<template>
<div class="sp-app">
  <header class="sp-header"><RouterLink class="sp-brand" to="/home"><b>S</b> SmartProp</RouterLink>
    <nav aria-label="Điều hướng chính"><RouterLink to="/listings">Tìm nhà đất</RouterLink><RouterLink to="/map">Bản đồ</RouterLink><template v-if="session.user"><RouterLink to="/favorites">Yêu thích</RouterLink><RouterLink to="/my-listing">Tin của tôi</RouterLink><RouterLink v-if="['BROKER','ADMIN'].includes(session.user.role)" to="/post">Đăng tin</RouterLink><RouterLink to="/account/reports">Báo cáo của tôi</RouterLink><RouterLink v-if="session.user.role==='ADMIN'" to="/admin/dashboard">Quản trị</RouterLink><RouterLink to="/account">{{session.user.fullName}}</RouterLink><button :disabled="busy" @click="signOut">Đăng xuất</button></template><RouterLink v-else to="/login">Đăng nhập</RouterLink></nav>
  </header><p v-if="error" class="sp-error" role="alert">{{error}}</p><main class="sp-main"><slot /></main><footer class="sp-footer">SmartProp · Bất động sản Đà Nẵng</footer>
</div>
</template>
